insert into public.exercises
  (id, title_pl, title_en, description_pl, description_en, body_region, condition_tags, tissue_tags, goal_tags, difficulty_level, equipment, position, contraindications, red_flags, sets, reps, duration_seconds, frequency_per_week, progression, regression, image_url, video_url, source_url, license_note)
values
('1a6bcaec-1e1e-0dc3-9dbf-37bbd648607f', 'Napięcia izometryczne mięśnia czworogłowego', 'Quadriceps isometric set', 'Siad lub leżenie z wyprostowaną nogą. Napnij mięsień uda, dociskając kolano do podłoża, przytrzymaj 5 s, rozluźnij.', 'Tighten the thigh, pressing the knee down. Hold 5 s, relax.', 'knee', '{post_acl,patellofemoral_pain}', '{muscle}', '{strength,motor_control}', 1, '{none}', 'long_sitting', '{acute_inflammation}', '{}', 3, 10, null, 5, 'Dodaj uniesienie pięty (straight leg raise).', 'Zmniejsz siłę napięcia i czas trzymania do 3 s.', null, null, null, 'placeholder'),
('4d0b04d4-870b-64fb-e464-26c3722ce15a', 'Uniesienie wyprostowanej nogi (SLR)', 'Straight leg raise', 'Leżenie na plecach, jedna noga zgięta. Napnij udo i unieś wyprostowaną nogę ~30 cm, opuść z kontrolą.', 'Lift the straight leg ~30 cm with the thigh engaged, lower slowly.', 'knee', '{post_acl,patellofemoral_pain}', '{muscle}', '{strength}', 2, '{none}', 'supine', '{acute_inflammation}', '{}', 3, 12, null, 4, 'Dodaj obciążnik na kostkę 1–2 kg.', 'Zmniejsz wysokość uniesienia.', null, null, null, 'placeholder'),
('cdb19a27-456d-1a32-bd28-a6f7e6117c8d', 'Mini przysiad przy ścianie', 'Wall mini-squat', 'Plecami do ściany, stopy lekko wysunięte. Zegnij kolana do ~45°, utrzymaj 5–10 s, wróć do wyprostu.', 'Slide down the wall to ~45° knee bend, hold, return.', 'knee', '{post_acl,patellofemoral_pain,general_deconditioning}', '{muscle}', '{strength,stability}', 3, '{wall}', 'standing', '{acute_inflammation,severe_pain,instability}', '{}', 3, 10, null, 4, 'Zwiększ głębokość lub czas trzymania; przejdź do przysiadu bez ściany.', 'Zmniejsz zakres zgięcia kolan.', null, null, null, 'placeholder'),
('6f164c7d-468b-1baf-a1d6-a787c0476d3a', 'Izometryczny wyprost nadgarstka', 'Isometric wrist extension', 'Przedramię oparte, dłoń poza krawędzią. Drugą ręką stawiaj opór, próbując unieść grzbiet dłoni. Trzymaj 10–20 s bez ruchu.', 'Resist wrist extension isometrically, holding 10–20 s.', 'elbow', '{lateral_epicondylalgia,tendinopathy}', '{tendon,muscle}', '{strength,pain_relief}', 1, '{none}', 'seated', '{severe_pain}', '{}', 4, 5, 15, 5, 'Przejdź do powolnych ruchów ekscentrycznych z lekkim ciężarem.', 'Zmniejsz siłę oporu i czas trzymania.', null, null, null, 'placeholder'),
('cb36b257-f877-1e5b-3f0d-c406518ea968', 'Ekscentryczny wyprost nadgarstka z ciężarem', 'Eccentric wrist extension', 'Z lekkim ciężarem w dłoni opuszczaj nadgarstek powoli (3–4 s). Drugą ręką wracaj do pozycji wyjściowej.', 'Lower the weighted wrist slowly (3–4 s); assist the return with the other hand.', 'elbow', '{lateral_epicondylalgia,tendinopathy}', '{tendon,muscle}', '{strength}', 2, '{light_weight}', 'seated', '{severe_pain,acute_inflammation}', '{}', 3, 12, null, 4, 'Zwiększ ciężar o 0,5 kg, gdy 3×12 jest bezbolesne.', 'Zmniejsz ciężar lub wykonuj bez obciążenia.', null, null, null, 'placeholder'),
('3a7cfe38-ae2c-7da1-b0dd-e8fbdec3f545', 'Rozciąganie zginaczy biodra w półklęku', 'Half-kneeling hip flexor stretch', 'W półklęku przenieś ciężar do przodu, utrzymując miednicę w lekkim podwinięciu. Poczuj rozciąganie z przodu biodra.', 'In half-kneeling, shift forward to stretch the front of the hip.', 'hip', '{hip_impingement,postural_overload}', '{muscle}', '{mobility,stretch}', 1, '{none}', 'half_kneeling', '{acute_inflammation}', '{}', 2, null, 30, 5, 'Dodaj delikatne wznosy ramienia po stronie rozciąganej.', 'Zmniejsz wykrok i zakres ruchu.', null, null, null, 'placeholder'),
('a8080494-8422-6fa9-20ef-2a1b5a565b8a', 'Mostek biodrowy', 'Glute bridge', 'Leżenie na plecach, stopy oparte. Unieś biodra napinając pośladki, utrzymaj 2 s, opuść z kontrolą.', 'Lift the hips by squeezing the glutes, hold 2 s, lower.', 'hip', '{hip_impingement,mechanical_low_back_pain,general_deconditioning}', '{muscle}', '{strength,stability}', 2, '{none}', 'supine', '{acute_inflammation}', '{}', 3, 12, null, 4, 'Wykonuj na jednej nodze.', 'Zmniejsz wysokość uniesienia bioder.', null, null, null, 'placeholder'),
('89ec0c06-2797-f6f9-d5b4-67f0cc5c76ad', 'Koci grzbiet (cat–camel)', 'Cat–camel', 'W klęku podpartym płynnie wyginaj i zaokrąglaj kręgosłup w rytm oddechu, w zakresie bezbolesnym.', 'On all fours, gently arch and round the spine with breathing.', 'lower_back', '{mechanical_low_back_pain,postural_overload}', '{joint_capsule,muscle}', '{mobility,pain_relief}', 1, '{none}', 'quadruped', '{severe_pain}', '{neuro_bilateral,bladder_bowel}', 2, 10, null, 6, 'Zwiększ zakres ruchu w obu kierunkach.', 'Zmniejsz zakres; wykonuj wolniej.', null, null, null, 'placeholder'),
('0cefb269-bc0b-8e09-941e-b2bb572c17a7', 'Ptak–pies (bird-dog)', 'Bird-dog', 'W klęku podpartym wyprostuj przeciwległą rękę i nogę, utrzymując stabilny tułów. Wróć i zmień stronę.', 'Extend opposite arm and leg keeping the trunk stable; alternate.', 'lower_back', '{mechanical_low_back_pain,postural_overload}', '{muscle}', '{stability,motor_control,strength}', 2, '{none}', 'quadruped', '{severe_pain}', '{neuro_bilateral,bladder_bowel}', 3, 10, null, 4, 'Dodaj przytrzymanie 3–5 s w wyproście.', 'Wyprostuj tylko rękę albo tylko nogę.', null, null, null, 'placeholder'),
('7a2f267f-fa0a-b9d6-737c-ebef32ad2842', 'Rozciąganie klatki i otwarcie odcinka piersiowego', 'Thoracic opener', 'Siedząc lub stojąc, splataj dłonie za głową i delikatnie otwieraj klatkę, prostując odcinek piersiowy.', 'Open the chest and extend the thoracic spine gently.', 'thoracic', '{postural_overload}', '{muscle,joint_capsule}', '{mobility,stretch,pain_relief}', 1, '{chair}', 'seated', '{}', '{}', 2, 10, null, 6, 'Wykonaj nad oparciem krzesła dla większego zakresu.', 'Zmniejsz zakres wyprostu.', null, null, null, 'placeholder'),
('306e1eff-6749-f995-bab9-56b045dc3a0f', 'Spacer w komfortowym tempie', 'Comfortable-pace walking', 'Regularny spacer poprawiający krążenie i ogólną tolerancję wysiłku. Zacznij od krótkich dystansów i wydłużaj stopniowo.', 'Regular walking to build circulation and tolerance.', 'general', '{general_deconditioning,osteoarthritis}', '{}', '{circulation,pain_relief}', 1, '{none}', 'standing', '{}', '{chest_systemic}', 1, null, 600, 5, 'Wydłużaj czas o 5 min tygodniowo.', 'Skróć czas i tempo.', null, null, null, 'placeholder'),
('ce0ecb45-6217-b99b-fe90-1fdcbc2517cd', 'Delikatne przytaknięcia głową (kiwanie)', 'Gentle cranio-cervical nod', 'Siedząc, wykonaj delikatny ruch „tak” — chowając brodę, jakbyś trzymał jajko pod brodą. Bez napinania ramion.', 'Seated gentle chin-nod (deep neck flexor activation) without shrugging.', 'neck', '{neck_pain,postural_overload}', '{muscle}', '{motor_control,pain_relief}', 1, '{none}', 'seated', '{severe_pain}', '{}', 2, 10, null, 6, 'Przytrzymaj pozycję 5 s przy każdym powtórzeniu.', 'Zmniejsz zakres ruchu do minimum.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('4a77cbe4-8c38-6a59-8680-633fa8668286', 'Rotacja szyi w zakresie bezbolesnym', 'Pain-free neck rotation', 'Powoli obracaj głowę w prawo i w lewo tylko tak daleko, jak jest komfortowo. Wracaj do środka między powtórzeniami.', 'Slow active neck rotation within a comfortable range.', 'neck', '{neck_pain}', '{joint_capsule,muscle}', '{mobility}', 1, '{none}', 'seated', '{severe_pain}', '{}', 2, 8, null, 6, 'Stopniowo zwiększaj zakres rotacji.', 'Wykonuj z mniejszą amplitudą i wolniej.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('64d3c3bb-9966-88b6-64eb-c6963c045e54', 'Rozciąganie mięśnia czworobocznego (góra)', 'Upper trapezius stretch', 'Siedząc, delikatnie przyciągnij ucho do barku, pomagając jedną ręką. Drugi bark ciągnij w dół. Trzymaj bez bólu.', 'Seated upper trapezius stretch, opposite shoulder reaching down.', 'neck', '{neck_pain,postural_overload}', '{muscle}', '{stretch,mobility}', 1, '{none}', 'seated', '{}', '{}', 2, null, 30, 6, 'Wydłuż czas trzymania do 45 s.', 'Zmniejsz nacisk ręki i zakres.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('fc4ed20e-308c-efed-c1c5-c16a0886b575', 'Ściąganie łopatek (setting)', 'Scapular setting', 'Delikatnie ściągnij łopatki w dół i do tyłu, jakbyś chował je do tylnych kieszeni. Trzymaj 5 s, rozluźnij.', 'Gentle scapular retraction/depression holds.', 'neck', '{neck_pain,postural_overload,thoracic_stiffness}', '{muscle}', '{motor_control,strength}', 2, '{none}', 'seated', '{}', '{}', 3, 10, null, 5, 'Dodaj lekką taśmę oporową.', 'Skróć czas trzymania do 2 s.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('da2240f1-26fb-5ba1-c09c-7b69a5bb6f07', 'Delikatny ślizg nerwowy kończyny górnej', 'Gentle upper-limb nerve glide', 'Odwiedź rękę w bok z dłonią skierowaną w dół; delikatnie odchyl nadgarstek i wróć. Ruch płynny, BEZ prowokowania drętwienia.', 'Gentle median nerve glide; never push into numbness.', 'neck', '{cervical_radiculopathy}', '{nerve}', '{neural_glide,mobility}', 1, '{none}', 'seated', '{severe_pain}', '{}', 2, 8, null, 5, 'Delikatnie zwiększ zakres, jeśli objawy nie narastają.', 'Zmniejsz zakres; ruch tylko nadgarstka.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('0bed9477-d687-55ab-e561-dfe0c102bdea', 'Wahadło Codmana', 'Codman pendulum', 'Pochyl tułów, pozwól ramieniu zwisać i zataczaj nim małe kręgi siłą tułowia, rozluźniając bark.', 'Relaxed pendular circles to decompress the shoulder.', 'shoulder', '{shoulder_impingement,frozen_shoulder,rotator_cuff_tendinopathy}', '{joint_capsule}', '{mobility,pain_relief}', 1, '{none}', 'standing', '{severe_pain}', '{}', 2, null, 45, 6, 'Powiększ średnicę kręgów.', 'Mniejsze kręgi, krótszy czas.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('53d77bde-cef9-4d76-daa5-59978ed47c61', 'Wspinanie palcami po ścianie', 'Wall finger walk', 'Stojąc bokiem/przodem do ściany, „wspinaj się” palcami w górę do granicy komfortu, potem zejdź.', 'Finger walk up the wall to gradually increase elevation.', 'shoulder', '{frozen_shoulder,shoulder_impingement}', '{joint_capsule,muscle}', '{mobility,stretch}', 1, '{wall}', 'standing', '{severe_pain}', '{}', 3, 8, null, 6, 'Sięgaj wyżej przy każdej serii.', 'Zmniejsz wysokość docelową.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('8419758a-4e75-b9aa-63b4-8d4ba2f2bf89', 'Rotacja zewnętrzna z taśmą (przy tułowiu)', 'Band external rotation at side', 'Łokieć przy boku zgięty 90°, taśma z przodu. Obracaj przedramię na zewnątrz, kontrolując powrót.', 'Elbow-at-side band external rotation for the rotator cuff.', 'shoulder', '{rotator_cuff_tendinopathy,shoulder_impingement}', '{tendon,muscle}', '{strength,motor_control}', 2, '{resistance_band}', 'standing', '{acute_inflammation,severe_pain}', '{}', 3, 12, null, 4, 'Zwiększ opór taśmy.', 'Słabsza taśma lub mniejszy zakres.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('1e778875-3e22-a959-745f-96ae5758c076', 'Unoszenie w płaszczyźnie łopatki (scaption)', 'Scaption raise', 'Unoś wyprostowane ramiona pod kątem ~30° do przodu (kciuki w górę) do wysokości barków, opuść z kontrolą.', 'Thumbs-up raises in the scapular plane to shoulder height.', 'shoulder', '{rotator_cuff_tendinopathy,shoulder_impingement}', '{tendon,muscle}', '{strength,stability}', 3, '{light_weight}', 'standing', '{acute_inflammation,severe_pain,instability}', '{}', 3, 12, null, 4, 'Zwiększ ciężar o 0,5 kg.', 'Bez obciążenia, do wysokości poniżej barku.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('50423f7a-3c0d-9e5e-92be-d16ec23bfd6c', 'Rozciąganie tylnej torebki (sleeper stretch)', 'Sleeper stretch', 'Leżąc na boku, ramię w przód 90°, delikatnie obracaj przedramię w dół do uczucia rozciągania z tyłu barku.', 'Side-lying posterior capsule stretch.', 'shoulder', '{shoulder_impingement,frozen_shoulder}', '{joint_capsule}', '{stretch,mobility}', 2, '{mat}', 'side_lying', '{severe_pain}', '{}', 2, null, 30, 5, 'Wydłuż czas do 45 s.', 'Zmniejsz nacisk i zakres.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('3d7bae2c-d053-8d58-df55-75be73806e43', 'Izometryczne zginanie nadgarstka (łokieć golfisty)', 'Isometric wrist flexion (golfer)', 'Przedramię oparte, dłoń poza krawędzią. Stawiaj opór drugą ręką, napinając zginacze nadgarstka bez ruchu.', 'Isometric wrist flexion hold for medial epicondylalgia.', 'elbow', '{medial_epicondylalgia,tendinopathy}', '{tendon,muscle}', '{strength,pain_relief}', 1, '{none}', 'seated', '{severe_pain}', '{}', 4, 5, 15, 5, 'Przejdź do powolnych ruchów ekscentrycznych z lekkim ciężarem.', 'Zmniejsz siłę napięcia i czas.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('fb87795e-321a-6bea-5d2d-fffd8d41453d', 'Rozciąganie prostowników nadgarstka', 'Wrist extensor stretch', 'Wyprostuj rękę przed sobą, dłonią w dół; drugą ręką delikatnie zginaj nadgarstek w dół do rozciągania przedramienia.', 'Gentle wrist extensor stretch.', 'elbow', '{lateral_epicondylalgia,tendinopathy}', '{tendon,muscle}', '{stretch,mobility}', 1, '{none}', 'seated', '{}', '{}', 2, null, 30, 6, 'Wydłuż czas do 45 s.', 'Zmniejsz zakres zgięcia.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('2f1a1ea3-fb3c-e869-cbd7-4cad6b01aa16', 'Ślizg nerwu pośrodkowego (cieśń nadgarstka)', 'Median nerve glide (carpal tunnel)', 'Sekwencja pozycji dłoni i nadgarstka (pięść → wyprost palców → odchylenie nadgarstka) płynnie, bez prowokowania drętwienia.', 'Median nerve gliding sequence; avoid provoking numbness.', 'wrist_hand', '{carpal_tunnel}', '{nerve}', '{neural_glide,mobility}', 1, '{none}', 'seated', '{severe_pain}', '{}', 2, 8, null, 5, 'Dodaj delikatne odchylenie głowy w przeciwną stronę.', 'Skróć sekwencję do 2 pozycji.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('ccf8bcf3-308a-7f12-426d-4d8ca48296e6', 'Ślizgi ścięgien zginaczy palców', 'Finger flexor tendon glides', 'Z pozycji wyprostowanych palców przechodź kolejno przez „haczyk”, pięść prostą i pełną pięść. Powoli i bezboleśnie.', 'Finger flexor tendon gliding sequence.', 'wrist_hand', '{carpal_tunnel,general_mobility}', '{tendon}', '{mobility}', 1, '{none}', 'seated', '{}', '{}', 2, 8, null, 6, 'Zwiększ liczbę powtórzeń.', 'Wykonuj wolniej, mniejszy zakres.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('055582c7-b371-e117-71d9-cdabae7c84b2', 'Ekscentryczne zginanie nadgarstka z ciężarem', 'Eccentric wrist flexion', 'Z lekkim ciężarem, dłoń w górę: powoli (3–4 s) opuszczaj nadgarstek w dół, wracaj z pomocą drugiej ręki.', 'Slow eccentric wrist flexion with light weight.', 'elbow', '{medial_epicondylalgia,tendinopathy}', '{tendon,muscle}', '{strength}', 2, '{light_weight}', 'seated', '{acute_inflammation,severe_pain}', '{}', 3, 12, null, 4, 'Zwiększ ciężar o 0,5 kg przy 3×12 bez bólu.', 'Bez ciężaru lub mniejszy zakres.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('454b73de-053d-6014-5109-4e3fdbc82569', 'Mobilizacja piersiowa na rollerze', 'Thoracic extension over foam roller', 'Roller w poprzek pleców na wysokości łopatek; podpierając głowę delikatnie wyginaj odcinek piersiowy do tyłu.', 'Supported thoracic extensions over a foam roller.', 'thoracic', '{thoracic_stiffness,postural_overload}', '{joint_capsule,muscle}', '{mobility,pain_relief}', 2, '{foam_roller,mat}', 'supine', '{osteoporosis_caution}', '{}', 2, 8, null, 5, 'Pracuj na kolejnych segmentach piersiowych.', 'Zmniejsz zakres wyprostu; użyj ręcznika zamiast rollera.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('08a61899-5cc5-8c3f-da80-cc30f5a69c88', 'Otwieranie książki (open book)', 'Open-book thoracic rotation', 'Leżąc na boku z kolanami zgiętymi, prowadź górną rękę po łuku otwierając klatkę i obracając odcinek piersiowy.', 'Side-lying open-book thoracic rotation.', 'thoracic', '{thoracic_stiffness,postural_overload}', '{joint_capsule,muscle}', '{mobility,stretch}', 1, '{mat}', 'side_lying', '{}', '{}', 2, 8, null, 6, 'Zatrzymaj na końcu zakresu 2–3 s.', 'Zmniejsz zakres rotacji.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('af50bd26-dba2-7403-b23e-a3bfafcf82ec', 'Koci grzbiet z naciskiem na odcinek piersiowy', 'Thoracic-focused cat–camel', 'W klęku podpartym płynnie zaokrąglaj i prostuj głównie odcinek piersiowy, oddychając swobodnie.', 'Cat–camel emphasising the thoracic spine.', 'thoracic', '{thoracic_stiffness,general_mobility}', '{joint_capsule}', '{mobility}', 1, '{mat}', 'quadruped', '{}', '{}', 2, 10, null, 6, 'Zwiększ zakres ruchu.', 'Mniejszy zakres, wolniej.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('b0968bcb-f87e-0b96-f2e0-a77d4aa1e0bf', 'Anioł przy ścianie', 'Wall angel', 'Plecami do ściany, dolny odcinek pleców blisko ściany. Prowadź ręce w górę i w dół, utrzymując kontakt nadgarstków ze ścianą.', 'Wall angels for postural control of the upper back.', 'thoracic', '{postural_overload,thoracic_stiffness}', '{muscle}', '{motor_control,mobility}', 2, '{wall}', 'standing', '{}', '{}', 3, 10, null, 5, 'Zwiększ zakres unoszenia ramion.', 'Zmniejsz zakres; oddal stopy od ściany.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('c3025ab9-5a51-7928-1fdd-bf650ed0266e', 'Rotacja tułowia na krześle', 'Seated thoracic rotation', 'Siedząc, ręce skrzyżowane na barkach, delikatnie obracaj tułów w prawo i lewo w zakresie bezbolesnym.', 'Seated thoracic rotation with arms crossed.', 'thoracic', '{thoracic_stiffness,postural_overload}', '{joint_capsule,muscle}', '{mobility}', 1, '{chair}', 'seated', '{}', '{}', 2, 10, null, 6, 'Dodaj krótki wydech na końcu zakresu.', 'Zmniejsz zakres rotacji.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('6742448e-9fec-0a0b-b229-87e57f898042', 'Tyłozgięcie miednicy (pelvic tilt)', 'Posterior pelvic tilt', 'Leżąc na plecach z ugiętymi kolanami, delikatnie dociśnij dolny odcinek pleców do podłoża, napinając brzuch. Rozluźnij.', 'Supine posterior pelvic tilt with gentle core activation.', 'lower_back', '{mechanical_low_back_pain,postural_overload}', '{muscle}', '{motor_control,pain_relief}', 1, '{mat}', 'supine', '{}', '{neuro_bilateral,bladder_bowel}', 2, 10, null, 6, 'Przytrzymaj napięcie 5 s.', 'Zmniejsz napięcie i zakres.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('9e5e074e-18a8-d368-1ddb-ddd201e0cbf0', 'Przyciąganie kolan do klatki', 'Knee-to-chest stretch', 'Leżąc, delikatnie przyciągnij jedno lub oba kolana do klatki do uczucia rozciągania w dolnych plecach.', 'Supine single/double knee-to-chest stretch.', 'lower_back', '{mechanical_low_back_pain}', '{muscle,joint_capsule}', '{stretch,mobility,pain_relief}', 1, '{mat}', 'supine', '{}', '{neuro_bilateral,bladder_bowel}', 2, null, 30, 6, 'Przytrzymaj dłużej, dodaj delikatne kołysanie.', 'Jedno kolano na raz, mniejszy zakres.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('e5dcad41-5ff1-2e87-2124-c45c50dfe4ab', 'Mostek biodrowy (stabilizacja lędźwi)', 'Glute bridge for lumbar control', 'Leżąc z ugiętymi kolanami unieś biodra napinając pośladki, utrzymując neutralny kręgosłup. Opuść z kontrolą.', 'Glute bridge maintaining a neutral spine.', 'lower_back', '{mechanical_low_back_pain,postural_overload}', '{muscle}', '{strength,stability}', 2, '{mat}', 'supine', '{severe_pain}', '{neuro_bilateral,bladder_bowel}', 3, 12, null, 4, 'Mostek na jednej nodze.', 'Mniejsza wysokość uniesienia.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('9f46fdda-b2e7-952a-290a-ee6d155d30d5', 'Dead bug (martwy robak)', 'Dead bug', 'Leżąc, ręce w górę, kolana zgięte 90°. Naprzemiennie opuszczaj przeciwległą rękę i nogę, utrzymując stabilny tułów.', 'Dead bug for anti-extension core control.', 'lower_back', '{mechanical_low_back_pain,postural_overload}', '{muscle}', '{stability,motor_control,strength}', 2, '{mat}', 'supine', '{severe_pain}', '{neuro_bilateral,bladder_bowel}', 3, 10, null, 4, 'Wolniejsze tempo, dłuższy wyprost kończyn.', 'Ruszaj tylko nogami lub tylko rękami.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('873ac3e9-1817-0c93-134e-8bc07e326324', 'Deska bok na kolanach', 'Side plank from knees', 'Podpór bokiem na przedramieniu i kolanach; unieś biodra w linię ciała, utrzymaj, opuść z kontrolą.', 'Modified side plank on knees for lateral core.', 'lower_back', '{mechanical_low_back_pain}', '{muscle}', '{strength,stability}', 3, '{mat}', 'side_lying', '{severe_pain,acute_inflammation}', '{neuro_bilateral,bladder_bowel}', 3, null, 20, 4, 'Pełna deska bok z wyprostowanych nóg.', 'Skróć czas trzymania.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('346a4565-3a40-a6e9-59b9-40ebe75dac3d', 'Delikatny wyprost w leżeniu (prone on elbows)', 'Prone prop on elbows', 'Leżąc na brzuchu, podeprzyj się na przedramionach, pozwalając biodrom rozluźnić się. Pozostań, jeśli nie nasila objawów.', 'Prone prop extension; stop if it peripheralises symptoms.', 'lower_back', '{mechanical_low_back_pain}', '{joint_capsule}', '{mobility,pain_relief}', 1, '{mat}', 'prone', '{severe_pain}', '{neuro_bilateral,bladder_bowel}', 2, null, 30, 5, 'Wydłuż czas; jeśli komfortowo, delikatne uniesienia.', 'Leżenie płaskie z poduszką pod brzuchem.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('bdd19f22-ae15-907e-a18d-fa186ba49fa7', 'Delikatny ślizg nerwu kulszowego', 'Gentle sciatic nerve glide', 'Siedząc, powoli prostuj kolano i unoś palce stopy ku sobie, gdy głowa odchyla się lekko w tył; wracaj. BEZ prowokowania bólu nogi.', 'Seated sciatic nerve slider; avoid provoking leg symptoms.', 'lower_back', '{sciatica}', '{nerve}', '{neural_glide,mobility}', 1, '{chair}', 'seated', '{severe_pain}', '{neuro_bilateral,bladder_bowel}', 2, 8, null, 5, 'Delikatnie zwiększ zakres, jeśli objawy nie narastają.', 'Mniejszy zakres; sam ruch stopy.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('52075b0b-5fae-182a-d64d-47830098a0ad', 'Rozciąganie pośladka (figura 4)', 'Figure-4 glute/piriformis stretch', 'Leżąc, załóż kostkę na przeciwne kolano i przyciągnij udo do siebie do rozciągania pośladka. Bez bólu promieniującego.', 'Supine figure-4 gluteal stretch.', 'lower_back', '{sciatica,mechanical_low_back_pain,gluteal_tendinopathy}', '{muscle}', '{stretch,mobility}', 1, '{mat}', 'supine', '{}', '{neuro_bilateral,bladder_bowel}', 2, null, 30, 6, 'Wydłuż czas trzymania.', 'Mniejszy zakres przyciągnięcia.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('32b5e819-ed36-ce3b-21d0-d7edd1341b63', 'Bird-dog z przytrzymaniem', 'Bird-dog with hold', 'W klęku podpartym wyprostuj przeciwległą rękę i nogę, utrzymaj 3–5 s stabilny tułów, zmień stronę.', 'Bird-dog with a brief end-range hold.', 'lower_back', '{mechanical_low_back_pain,postural_overload}', '{muscle}', '{stability,motor_control,strength}', 3, '{mat}', 'quadruped', '{severe_pain}', '{neuro_bilateral,bladder_bowel}', 3, 8, null, 4, 'Dłuższe przytrzymanie lub lekki ciężar w dłoni.', 'Bez przytrzymania; tylko ręka lub noga.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('b4bb7e15-4317-58d0-c7ab-48b7b50fce4d', 'Nauka zawiasu biodrowego (hip hinge)', 'Hip hinge pattern', 'Stojąc, z neutralnym kręgosłupem odchylaj biodra w tył (jak zamykanie drzwi pośladkami) i wracaj, nie zaokrąglając pleców.', 'Hip-hinge motor pattern keeping a neutral spine.', 'lower_back', '{mechanical_low_back_pain,postural_overload}', '{muscle}', '{motor_control,strength}', 2, '{none}', 'standing', '{severe_pain}', '{neuro_bilateral,bladder_bowel}', 3, 10, null, 5, 'Dodaj lekki ciężar trzymany przy ciele.', 'Ćwicz z dłońmi na biodrach przy ścianie za pośladkami.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('be9a3842-2b65-54fd-9db9-53a8299606d4', 'Muszla (clamshell)', 'Clamshell', 'Leżąc na boku z ugiętymi kolanami, unoś górne kolano nie obracając miednicy. Kontroluj powrót.', 'Side-lying clamshell for hip abductors.', 'hip', '{gluteal_tendinopathy,hip_pain,hip_impingement}', '{muscle}', '{strength,stability}', 2, '{mat}', 'side_lying', '{acute_inflammation}', '{}', 3, 12, null, 4, 'Dodaj taśmę oporową wokół ud.', 'Zmniejsz zakres unoszenia.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('af20b05d-ee64-3f6c-a315-2ef40e252719', 'Odwodzenie nogi w leżeniu bokiem', 'Side-lying hip abduction', 'Leżąc na boku, unoś wyprostowaną górną nogę do ~30°, pięta lekko z tyłu, opuść z kontrolą.', 'Side-lying straight-leg hip abduction.', 'hip', '{gluteal_tendinopathy,hip_pain}', '{muscle,tendon}', '{strength,stability}', 2, '{mat}', 'side_lying', '{acute_inflammation}', '{}', 3, 12, null, 4, 'Dodaj obciążnik na kostkę.', 'Mniejszy zakres, wolniej.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('a0aeabb5-9f84-05fe-df73-3fb0415d3200', 'Izometryczne odwodzenie bioder (ściana)', 'Isometric hip abduction at wall', 'Stojąc bokiem do ściany, dociskaj zewnętrzną stronę kolana/uda do ściany, napinając pośladek. Trzymaj bez bólu.', 'Isometric gluteal abduction hold against a wall.', 'hip', '{gluteal_tendinopathy,hip_pain}', '{tendon,muscle}', '{strength,pain_relief}', 1, '{wall}', 'standing', '{}', '{}', 4, 5, 20, 5, 'Wydłuż czas trzymania do 30–40 s.', 'Zmniejsz siłę docisku.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('85e4a415-232a-d250-60e0-7b0cedbb1909', 'Mobilizacja bioder 90/90', '90/90 hip rotation', 'Siedząc na podłodze w pozycji 90/90, powoli przenoś kolana z boku na bok, mobilizując rotacje bioder.', '90/90 seated hip internal/external rotation mobility.', 'hip', '{hip_impingement,hip_pain,general_mobility}', '{joint_capsule,muscle}', '{mobility}', 2, '{mat}', 'seated', '{acute_inflammation}', '{}', 2, 10, null, 5, 'Zwiększ zakres lub dodaj lekki nacisk dłonią.', 'Mniejszy zakres przenoszenia kolan.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('9e71f962-8622-5260-b967-d6aebf04584d', 'Wstawanie z krzesła (sit-to-stand)', 'Sit-to-stand', 'Z siadu na krześle wstań bez pomocy rąk i usiądź z kontrolą. Pilnuj, by kolana podążały nad stopami.', 'Controlled sit-to-stand for functional leg strength.', 'hip', '{hip_pain,general_deconditioning,osteoarthritis}', '{muscle}', '{strength,stability}', 2, '{chair}', 'standing', '{}', '{}', 3, 10, null, 4, 'Użyj niższego siedziska lub trzymaj lekki ciężar.', 'Wyższe siedzisko lub lekkie podparcie rękami.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('0a8da4f6-72cc-96c9-ab2c-348f6bf0576f', 'Ślizgi pięty (zgięcie kolana)', 'Heel slides', 'Leżąc, powoli przesuwaj piętę do pośladka, zginając kolano w zakresie bezbolesnym, i wracaj.', 'Supine heel slides to restore knee flexion.', 'knee', '{post_acl,knee_pain,general_mobility}', '{joint_capsule}', '{mobility}', 1, '{mat}', 'supine', '{}', '{}', 2, 12, null, 6, 'Zwiększaj zakres zgięcia.', 'Mniejszy zakres, wspomagaj ręcznikiem.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('dc16f438-65e9-23f0-a8fa-8bde6d594a73', 'Izometryczny wyprost kolana w siadzie', 'Seated knee extension isometric', 'Siedząc, wyprostuj kolano i napnij udo, trzymając nogę uniesioną 5–10 s, opuść z kontrolą.', 'Seated isometric knee extension holds.', 'knee', '{patellofemoral_pain,knee_pain,osteoarthritis}', '{muscle}', '{strength}', 1, '{chair}', 'seated', '{acute_inflammation}', '{}', 3, 10, null, 5, 'Dodaj lekki obciążnik na kostkę.', 'Skróć czas trzymania.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('9489ca9a-21a7-06ff-f714-3e471f7d433b', 'Wejście na stopień (step-up)', 'Step-up', 'Wejdź na niski stopień prowadzoną nogą, kontrolując ustawienie kolana nad stopą; zejdź powoli.', 'Controlled step-ups with good knee alignment.', 'knee', '{patellofemoral_pain,post_acl,knee_pain}', '{muscle}', '{strength,stability}', 3, '{step}', 'standing', '{acute_inflammation,severe_pain,instability}', '{}', 3, 10, null, 4, 'Wyższy stopień lub lekki ciężar.', 'Niższy stopień; przytrzymaj się poręczy.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('8be2c89c-4791-a9b7-d5c7-bc9ea14ea5e1', 'Terminalny wyprost kolana z taśmą', 'Terminal knee extension (band)', 'Taśma za kolanem; prostuj kolano do pełnego wyprostu przeciw oporowi taśmy, napinając udo.', 'Banded terminal knee extension.', 'knee', '{post_acl,patellofemoral_pain}', '{muscle}', '{strength,motor_control}', 2, '{resistance_band}', 'standing', '{acute_inflammation}', '{}', 3, 15, null, 4, 'Mocniejsza taśma.', 'Słabsza taśma lub bez oporu.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('a68f8b9b-799c-24f4-f6a7-dce99d9f176c', 'Zginanie kolana stojąc', 'Standing hamstring curl', 'Stojąc z podparciem, zginaj kolano, przyciągając piętę do pośladka, i wracaj z kontrolą.', 'Standing hamstring curl with support.', 'knee', '{post_acl,knee_pain}', '{muscle}', '{strength}', 2, '{chair}', 'standing', '{acute_inflammation}', '{}', 3, 12, null, 4, 'Dodaj obciążnik na kostkę lub taśmę.', 'Mniejszy zakres, wolniej.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('cb5c5489-ade3-7253-4ad8-3928ba35396d', 'Przysiad izometryczny przy ścianie (wall sit)', 'Wall sit', 'Plecami do ściany zejdź do kąta bezbolesnego (np. 30–60°) i utrzymaj pozycję, oddychając swobodnie.', 'Isometric wall sit at a pain-free angle.', 'knee', '{patellofemoral_pain,knee_pain}', '{muscle}', '{strength,pain_relief}', 2, '{wall}', 'standing', '{acute_inflammation,severe_pain}', '{}', 3, null, 30, 4, 'Wydłuż czas lub zejdź głębiej.', 'Mniejszy kąt zgięcia, krótszy czas.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('04ddd49f-84e5-59e3-1be0-66da2215788a', 'Wspięcia na palce (wsparcie)', 'Supported calf raise', 'Z lekkim podparciem unieś się na palce obu stóp i powoli opuść. Kontroluj równowagę.', 'Supported double-leg calf raises.', 'knee', '{knee_pain,general_deconditioning}', '{muscle,tendon}', '{strength,stability}', 1, '{chair}', 'standing', '{}', '{}', 3, 12, null, 4, 'Wspięcia na jednej nodze.', 'Mniejszy zakres, wolniej.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('8396c475-4a49-8dc7-6b5b-e69cf39db3c3', 'Rozciąganie mięśnia czworogłowego (stojąc)', 'Standing quadriceps stretch', 'Stojąc z podparciem, przyciągnij piętę do pośladka do rozciągania przodu uda, trzymając kolana razem.', 'Standing quadriceps stretch with support.', 'knee', '{patellofemoral_pain,knee_pain,general_mobility}', '{muscle}', '{stretch,mobility}', 1, '{chair}', 'standing', '{}', '{}', 2, null, 30, 6, 'Wydłuż czas trzymania.', 'Mniejszy zakres; użyj ręcznika wokół kostki.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('1ed8eb8b-5ff2-ea9a-6223-ccfc00993749', 'Mini przysiad z podparciem', 'Supported mini-squat', 'Trzymając się oparcia, zegnij kolana do ~30–45° i wróć, pilnując kierunku kolan nad stopami.', 'Supported shallow squat with good alignment.', 'knee', '{knee_pain,patellofemoral_pain,osteoarthritis}', '{muscle}', '{strength,stability}', 2, '{chair}', 'standing', '{acute_inflammation,severe_pain}', '{}', 3, 12, null, 4, 'Bez podparcia lub większy zakres.', 'Mniejszy zakres, większe podparcie.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('a1ad0a33-d2e8-ba50-4785-405fce1ac7cd', 'Stanie na jednej nodze (kontrola kolana)', 'Single-leg stance', 'Stań na jednej nodze z lekkim podparciem; utrzymaj stabilne, lekko ugięte kolano nad stopą.', 'Single-leg balance with knee control.', 'knee', '{post_acl,patellofemoral_pain,balance_senior}', '{muscle}', '{balance,stability,motor_control}', 2, '{chair}', 'standing', '{instability}', '{}', 3, null, 20, 5, 'Bez podparcia; oczy zamknięte (bezpiecznie).', 'Większe podparcie, krótszy czas.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('6f2e2651-e875-db02-93b5-053e92b46189', 'Alfabet stopą', 'Ankle alphabet', 'Siedząc, „pisz” stopą litery w powietrzu, poruszając stawem skokowym w pełnym bezbolesnym zakresie.', 'Active ankle ROM by drawing the alphabet.', 'ankle_foot', '{ankle_sprain,general_mobility}', '{joint_capsule}', '{mobility}', 1, '{none}', 'seated', '{acute_inflammation}', '{}', 2, null, 60, 6, 'Większy zakres ruchu.', 'Mniejsze litery, wolniej.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('e8d1780d-e5f1-b2b3-0400-47ee8f79bc87', 'Ewersja stopy z taśmą', 'Band ankle eversion', 'Taśma wokół śródstopia; odciągaj stopę na zewnątrz przeciw oporowi i wracaj z kontrolą.', 'Resisted ankle eversion for lateral stability.', 'ankle_foot', '{ankle_sprain}', '{muscle,tendon}', '{strength,stability}', 2, '{resistance_band}', 'seated', '{acute_inflammation}', '{}', 3, 15, null, 5, 'Mocniejsza taśma.', 'Słabsza taśma, mniejszy zakres.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('25674ab9-3bdd-a096-3373-fadda9dbffbf', 'Równowaga na jednej nodze (staw skokowy)', 'Single-leg ankle balance', 'Stań na zajętej nodze z lekkim podparciem; utrzymaj równowagę, kontrolując drobne ruchy stopy.', 'Single-leg balance to retrain ankle proprioception.', 'ankle_foot', '{ankle_sprain,balance_senior}', '{ligament,muscle}', '{balance,stability}', 2, '{chair}', 'standing', '{acute_inflammation,instability}', '{}', 3, null, 30, 5, 'Miękkie podłoże lub oczy zamknięte (bezpiecznie).', 'Więcej podparcia, krótszy czas.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('dd8728bb-be82-5f48-1d48-07665ff68409', 'Wspięcia na palce (łydka/Achilles)', 'Calf/Achilles heel raise', 'Z podparciem unieś pięty, powoli opuść (faza ekscentryczna 3 s). Pracuj bezboleśnie.', 'Heel raises with slow eccentric for the Achilles.', 'ankle_foot', '{achilles_tendinopathy}', '{tendon,muscle}', '{strength}', 2, '{chair}', 'standing', '{acute_inflammation,severe_pain}', '{}', 3, 12, null, 4, 'Na jednej nodze lub z krawędzi stopnia.', 'Obie nogi, pełne podparcie, mniejszy zakres.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('995c40a2-1ea8-830d-1245-9cf8e514cb70', 'Rozciąganie łydki przy ścianie', 'Wall calf stretch', 'Wykrok do ściany, tylna noga wyprostowana, pięta na podłodze; poczuj rozciąganie łydki, trzymaj bez bólu.', 'Standing wall calf stretch.', 'ankle_foot', '{achilles_tendinopathy,general_mobility}', '{muscle,tendon}', '{stretch,mobility}', 1, '{wall}', 'standing', '{}', '{}', 2, null, 30, 6, 'Wydłuż czas; dodaj wariant z ugiętym kolanem.', 'Mniejszy wykrok, krótszy czas.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('4f41eeca-fd3c-c13f-d240-6df050009cef', 'Spokojny oddech przeponowy', 'Diaphragmatic breathing', 'Połóż dłoń na brzuchu; wdech nosem tak, by brzuch unosił się delikatnie, długi spokojny wydech. Bez napinania barków.', 'Calm diaphragmatic breathing to downregulate.', 'general', '{general_mobility,general_deconditioning}', '{}', '{breathing,pain_relief}', 1, '{none}', 'supine', '{}', '{}', 1, null, 180, 7, 'Wydłuż czas do 5 min.', 'Krótsze sesje 1–2 min.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('2c09fa94-615e-f512-412f-21605ce63ffe', 'Marsz w miejscu (rozruch)', 'Marching in place', 'Maszeruj w miejscu w komfortowym tempie, unosząc kolana na wysokość wygodną dla Ciebie. Z podparciem w razie potrzeby.', 'Gentle marching in place for circulation.', 'general', '{general_deconditioning,general_mobility,balance_senior}', '{}', '{circulation,mobility}', 1, '{none}', 'standing', '{}', '{chest_systemic}', 1, null, 120, 6, 'Wydłuż czas, unieś kolana wyżej.', 'Wolniej, z podparciem.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('73833398-42b2-b7e4-714e-d82babaeeaa4', 'Stanie w pozycji tandem (równowaga)', 'Tandem stance', 'Ustaw stopy jedna za drugą w linii, z lekkim podparciem; utrzymaj równowagę, patrząc przed siebie.', 'Tandem (heel-to-toe) stance for balance.', 'general', '{balance_senior}', '{}', '{balance,stability}', 2, '{chair}', 'standing', '{instability}', '{}', 3, null, 20, 6, 'Bez podparcia; dłuższy czas.', 'Szersza podstawa, pełne podparcie.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).'),
('ed0994f5-9990-788d-a6ef-c2bf5ea8f319', 'Chód stopa za stopą (linia)', 'Heel-to-toe walking', 'Idź wzdłuż linii, stawiając piętę tuż przed palcami drugiej stopy; w pobliżu blatu/ściany dla bezpieczeństwa.', 'Heel-to-toe gait drill for dynamic balance.', 'general', '{balance_senior}', '{}', '{balance,motor_control}', 2, '{none}', 'standing', '{instability}', '{}', 3, 10, null, 5, 'Dłuższy dystans; głowa w ruchu.', 'Trzymaj się blatu/ściany.', null, null, null, 'Oryginalny opis edukacyjny FizjoPlan (placeholder mediów).')
